   if(rand()<.13)continue;const wx=-w/2+1.6+c*(w-3.2)/Math.max(1,cols-1),wy=2.2+r*3.1;
   const lit=rand()<.22;const wm=lit?windowMat:mat(0x333e3e,.55);
