scene.add(new THREE.HemisphereLight(0xc7d7d2,0x414039,2.0));const sun=new THREE.DirectionalLight(0xffe6bc,2.3);sun.position.set(-75,100,-45);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-115;sun.shadow.camera.right=115;sun.shadow.camera.top=115;sun.shadow.camera.bottom=-115;sun.shadow.bias=-.00015;scene.add(sun);
