setTarget();
const ui={speed:document.querySelector('#speed'),gear:document.querySelector('#gear'),cash:document.querySelector('#cash'),speedLine:document.querySelector('#speed-line'),distance:document.querySelector('#mission-distance'),prompt:document.querySelector('#prompt'),toast:document.querySelector('#toast'),map:document.querySelector('#minimap'),start:document.querySelector('#start-screen'),pause:document.querySelector('#pause-screen'),end:document.querySelector('#end-screen')};
