function interact(){if(!started||paused||finished)return;const distance=taxi.position.distanceTo(target());if(distance>9)return;if(missionPhase==='pickup'){missionPhase='drop';velocity*=.45;setTarget();showToast('Passenger aboard — destination marked!')}else{const trip=taxi.position.distanceTo(vec(faresList[fare].p));const reward=Math.round(230+trip*1.12-Math.min(damage,120));cash+=Math.max(100,reward);fares++;damage=Math.max(0,damage-10);document.querySelector('#progress').style.width='100%';showToast(`FARE COMPLETE  +$${Math.max(100,reward)}`);if(fares>=5){finished=true;started=false;ui.end.classList.remove('hidden');document.querySelector('#end-copy').textContent=`You delivered all five passengers with ${Math.round(damage)} damage points. The streets are yours.`;document.querySelector('#final-cash').textContent=`$${String(cash).padStart(3,'0')}`;return}fare++;missionPhase='pickup';setTarget()}}
